example.code:
// Create a pattern and test if a URL matches
var pattern = UrlPattern.Create("https://example.com/users/:id");
bool isMatch = pattern.IsMatch("https://example.com/users/123"); // true

// Extract captured groups from a URL
var result = pattern.Match("https://example.com/users/456");
string userId = result?.Pathname.Groups["id"]; // "456"

// Use wildcards to match any value
var wildcardPattern = UrlPattern.Create("https://*.example.com/*");
wildcardPattern.IsMatch("https://api.example.com/data"); // true

// Create a collection of patterns for routing
var patterns = new UrlPatternCollection();
patterns.Add("https://example.com/api/users/:id");
patterns.Add("https://example.com/api/products/:id");
patterns.Add("https://example.com/static/*");

// Check if any pattern matches
bool isMatch = patterns.IsMatch("https://example.com/api/users/123"); // true

// Find the first matching pattern
var matchingPattern = patterns.FindPattern("https://example.com/api/products/456");

// Get match result with captured groups
var result = patterns.Match("https://example.com/api/users/789");
